changeSet.sql:
ALTER TABLE BT.STRATEGY ADD COLUMN IF NOT EXISTS LOGICAL_DELETE_IND CHAR(1);
ALTER TABLE BT.STRATEGY ADD COLUMN IF NOT EXISTS UPDATED_AT TIMESTAMPTZ;

UPDATE BT.STRATEGY
   SET LOGICAL_DELETE_IND = 'N'
 WHERE LOGICAL_DELETE_IND IS NULL;

UPDATE BT.STRATEGY
   SET UPDATED_AT = CREATED_AT
 WHERE UPDATED_AT IS NULL;

ALTER TABLE BT.STRATEGY ALTER COLUMN LOGICAL_DELETE_IND SET NOT NULL;
ALTER TABLE BT.STRATEGY ALTER COLUMN UPDATED_AT SET NOT NULL;
